'use strict';
const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d');
const $=s=>document.querySelector(s),types=[{name:'Brasa',color:'#ffa775',hp:100,speed:175,power:25},{name:'Musgo',color:'#b5e287',hp:150,speed:160,power:20},{name:'Bruma',color:'#9cdeed',hp:90,speed:220,power:22}];
let w,h,dpr,mode='menu',chosen=0,player,enemies=[],shots=[],gems=[],sparks=[],elapsed=0,spawn=0,fire=0,kills=0,level=1,xp=0,need=6,bossSpawned=false,last=0,keys={},touch=null,best=0;
try{best=Number(localStorage.getItem('guardianes-best'))||0}catch{}$('#record').textContent=best?`Tu récord: ${best} criaturas derrotadas`:'Una nueva historia empieza contigo.';
function resize(){w=innerWidth;h=innerHeight;dpr=Math.min(devicePixelRatio||1,2);canvas.width=w*dpr;canvas.height=h*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',resize);resize();
document.querySelectorAll('.creature').forEach(b=>b.onclick=()=>{chosen=+b.dataset.type;document.querySelectorAll('.creature').forEach(c=>c.classList.toggle('selected',c===b))});
function start(){player={x:0,y:0,...types[chosen],maxHp:types[chosen].hp,rate:.58,magnet:80,inv:0};enemies=[];shots=[];gems=[];sparks=[];elapsed=0;spawn=0;fire=0;kills=0;level=1;xp=0;need=6;bossSpawned=false;mode='play';$('#menu').hidden=true;$('#overlay').hidden=true;$('#hud').hidden=false;$('#hint').textContent='RECOGE CRISTALES PARA EVOLUCIONAR';keys={};hud()}
$('#start').onclick=start;
function pause(){if(mode==='play'){mode='pause';show('Un respiro en el bosque','Tu aventura te espera.',[{title:'Continuar ↗',fn:()=>{mode='play';$('#overlay').hidden=true}},{title:'Volver al inicio',fn:menu}])}else if(mode==='pause'){mode='play';$('#overlay').hidden=true}}
$('#pause').onclick=pause;addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();keys[e.key.toLowerCase()]=true;if(e.key==='Escape')pause()});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);addEventListener('blur',()=>{keys={};if(mode==='play')pause()});
canvas.addEventListener('pointerdown',e=>{if(mode!=='play')return;touch={id:e.pointerId,x:e.clientX,y:e.clientY,dx:0,dy:0};canvas.setPointerCapture(e.pointerId);$('#stick').hidden=false;$('#stick').style.left=(e.clientX-50)+'px';$('#stick').style.top=(e.clientY-50)+'px'});canvas.addEventListener('pointermove',e=>{if(!touch||touch.id!==e.pointerId)return;let dx=e.clientX-touch.x,dy=e.clientY-touch.y,len=Math.hypot(dx,dy)||1;touch.dx=dx/Math.max(40,len);touch.dy=dy/Math.max(40,len);$('#stick i').style.transform=`translate(${touch.dx*30}px,${touch.dy*30}px)`});function release(){touch=null;$('#stick').hidden=true}canvas.addEventListener('pointerup',release);canvas.addEventListener('pointercancel',release);
function show(title,desc,buttons){release();const el=$('#overlay');el.replaceChildren();let heading=document.createElement('h2');heading.textContent=title;el.append(heading);let p=document.createElement('p');p.textContent=desc;el.append(p);buttons.forEach(o=>{let b=document.createElement('button');b.textContent=o.title;if(o.desc){let s=document.createElement('small');s.textContent=o.desc;b.append(s)}b.onclick=o.fn;el.append(b)});el.hidden=false}
function menu(){mode='menu';$('#menu').hidden=false;$('#overlay').hidden=true;$('#hud').hidden=true;$('#hint').textContent='SUPERVIVENCIA · 5 MINUTOS · UN JEFE FINAL';$('#record').textContent=`Tu récord: ${best} criaturas derrotadas`}
const upgrades=[{title:'✹ Corazón de fuego',desc:'+25% de daño en tus ataques.',fn:()=>player.power*=1.25},{title:'❖ Ritmo salvaje',desc:'Dispara un 18% más rápido.',fn:()=>player.rate=Math.max(.12,player.rate*.82)},{title:'❧ Raíces de vida',desc:'+25 de vida máxima y recupera 40 de vida.',fn:()=>{player.maxHp+=25;player.hp=Math.min(player.maxHp,player.hp+40)}},{title:'➶ Viento del bosque',desc:'+15% de velocidad de movimiento.',fn:()=>player.speed*=1.15},{title:'✧ Llamada de cristal',desc:'+50% de alcance para recoger experiencia.',fn:()=>player.magnet*=1.5}];
function levelup(){xp-=need;level++;need=Math.round(need*1.3+2);mode='upgrade';let choices=[...upgrades].sort(()=>Math.random()-.5).slice(0,3);show('Elige tu evolución',`NIVEL ${level} · El bosque te hace más fuerte`,choices.map(u=>({...u,fn:()=>{u.fn();mode='play';$('#overlay').hidden=true;hud();if(xp>=need)levelup()}})))}
function finish(win){mode='end';best=Math.max(best,kills);try{localStorage.setItem('guardianes-best',best)}catch{}show(win?'El bosque vuelve a brillar.':'Tu historia no termina aquí.',`${win?'Victoria':'Sobreviviste'} · ${clock(elapsed)} · ${kills} derrotados · Nivel ${level}`,[{title:'Jugar otra vez ↗',fn:start},{title:'Elegir otro guardián',fn:menu}])}
function clock(s){return `${Math.floor(s/60).toString().padStart(2,'0')}:${Math.floor(s%60).toString().padStart(2,'0')}`}
function hud(){$('#hp').textContent=`♥ ${Math.ceil(player.hp)} / ${player.maxHp}`;$('#time').textContent=clock(elapsed);$('#kills').textContent=`✦ ${kills}`;$('#xpbar').style.width=`${Math.min(100,xp/need*100)}%`;$('#level').textContent=`NIVEL ${level}  ·  ${bossSpawned?'DERROTA AL GUARDIÁN DE LA NIEBLA':'AMANECER EN '+clock(Math.max(0,300-elapsed))}`}
function enemy(boss=false){let a=Math.random()*Math.PI*2,r=Math.hypot(w,h)/2+50;let heavy=Math.random()<.2;enemies.push({x:player.x+Math.cos(a)*r,y:player.y+Math.sin(a)*r,hp:boss?1600:heavy?65+elapsed*.35:30+elapsed*.2,max:boss?1600:0,r:boss?42:heavy?19:13,speed:boss?62:heavy?45+elapsed*.06:65+elapsed*.09,boss,heavy,hit:0})}
function burst(x,y,color){for(let i=0;i<8;i++){let a=Math.random()*7;sparks.push({x,y,vx:Math.cos(a)*80,vy:Math.sin(a)*80,life:.4,color})}}
function update(dt){elapsed+=dt;player.inv=Math.max(0,player.inv-dt);let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0);if(touch){dx=touch.dx;dy=touch.dy}let len=Math.max(1,Math.hypot(dx,dy));player.x+=dx/len*player.speed*dt;player.y+=dy/len*player.speed*dt;spawn-=dt;if(spawn<=0&&enemies.length<180){enemy();spawn=Math.max(.17,.95-elapsed*.0025)}if(elapsed>=300&&!bossSpawned){bossSpawned=true;enemy(true)}fire-=dt;if(fire<=0&&enemies.length){let target=enemies.reduce((a,b)=>Math.hypot(a.x-player.x,a.y-player.y)<Math.hypot(b.x-player.x,b.y-player.y)?a:b);let a=Math.atan2(target.y-player.y,target.x-player.x);shots.push({x:player.x,y:player.y,vx:Math.cos(a)*490,vy:Math.sin(a)*490,life:2});fire=player.rate}
for(let e of enemies){let x=player.x-e.x,y=player.y-e.y,d=Math.hypot(x,y)||1;e.x+=x/d*e.speed*dt;e.y+=y/d*e.speed*dt;e.hit=Math.max(0,e.hit-dt);if(d<e.r+15&&player.inv<=0){player.hp-=e.boss?25:10;player.inv=.7;burst(player.x,player.y,'#ff9988');if(player.hp<=0){player.hp=0;hud();finish(false);return}}}
for(let s of shots){s.x+=s.vx*dt;s.y+=s.vy*dt;s.life-=dt;for(let e of enemies){if(e.hp>0&&Math.hypot(e.x-s.x,e.y-s.y)<e.r+6){e.hp-=player.power;e.hit=.12;s.life=0;if(e.hp<=0){kills++;burst(e.x,e.y,e.boss?'#e7d4a0':'#99c9a6');gems.push({x:e.x,y:e.y,value:e.heavy?3:1});if(e.boss){hud();finish(true);return}}break}}}shots=shots.filter(s=>s.life>0);enemies=enemies.filter(e=>e.hp>0);
for(let g of gems){let dx=player.x-g.x,dy=player.y-g.y,d=Math.hypot(dx,dy);if(d<player.magnet){g.x+=dx*dt*8;g.y+=dy*dt*8}if(d<18){xp+=g.value;g.dead=true}}gems=gems.filter(g=>!g.dead);if(gems.length>600)gems.splice(0,gems.length-600);for(let p of sparks){p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt}sparks=sparks.filter(p=>p.life>0);hud();if(xp>=need)levelup()}
function circle(x,y,r,c){ctx.fillStyle=c;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill()}
function creature(x,y,r,color,evil=false,hit=false){ctx.save();ctx.translate(x,y);ctx.fillStyle='#0004';ctx.beginPath();ctx.ellipse(0,r*.85,r,r*.35,0,0,7);ctx.fill();ctx.fillStyle=hit?'#fff':color;ctx.beginPath();ctx.moveTo(-r*.8,-r*.2);ctx.lineTo(-r*.9,-r*1.35);ctx.lineTo(-r*.15,-r*.75);ctx.lineTo(r*.65,-r*1.25);ctx.lineTo(r*.85,0);ctx.fill();circle(0,0,r,hit?'#fff':color);circle(-r*.33,-r*.1,r*.14,evil?'#ffe1a7':'#142a28');circle(r*.33,-r*.1,r*.14,evil?'#ffe1a7':'#142a28');if(!evil){circle(-r*.4,r*.24,r*.12,'#ea8b7a88');circle(r*.4,r*.24,r*.12,'#ea8b7a88');ctx.strokeStyle='#28413b';ctx.beginPath();ctx.arc(0,r*.2,r*.16,0,Math.PI);ctx.stroke()}ctx.restore()}
function draw(t){ctx.clearRect(0,0,w,h);let playing=mode!=='menu',cx=playing?player.x:Math.sin(t*.00008)*80,cy=playing?player.y:0;let ox=w*(playing?.5:.74),oy=h*.53;ctx.fillStyle='#102727';ctx.fillRect(0,0,w,h);ctx.save();ctx.translate(ox-cx,oy-cy);let sx=Math.floor((cx-ox)/100)*100,sy=Math.floor((cy-oy)/100)*100;for(let x=sx;x<cx+w+100;x+=100)for(let y=sy;y<cy+h+100;y+=100){let seed=Math.sin(x*12.7+y*4.8)*437.5,n=seed-Math.floor(seed);ctx.strokeStyle='#244038';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x+20,y+29);ctx.lineTo(x+22,y+22);ctx.lineTo(x+25,y+28);ctx.stroke();if(n>.69){circle(x+62,y+60,16,'#0b2021');circle(x+59,y+52,12,'#1c3930');circle(x+66,y+47,10,'#244333')}if(n<.12){circle(x+65,y+30,2,'#aac37966')}}
if(playing){for(let g of gems){ctx.fillStyle='#bfe689';ctx.beginPath();ctx.moveTo(g.x,g.y-5);ctx.lineTo(g.x+4,g.y);ctx.lineTo(g.x,g.y+6);ctx.lineTo(g.x-4,g.y);ctx.fill()}for(let e of enemies){creature(e.x,e.y,e.r,e.boss?'#82699a':e.heavy?'#716c85':'#697f82',true,e.hit>0);if(e.boss){ctx.fillStyle='#25392d';ctx.fillRect(e.x-45,e.y-62,90,6);ctx.fillStyle='#e5ba9b';ctx.fillRect(e.x-45,e.y-62,90*Math.max(0,e.hp/e.max),6)}}for(let s of shots){ctx.shadowBlur=14;ctx.shadowColor=player.color;circle(s.x,s.y,5,player.color);ctx.shadowBlur=0}for(let p of sparks){ctx.globalAlpha=p.life/.4;circle(p.x,p.y,3,p.color)}ctx.globalAlpha=1;if(player.inv<=0||Math.floor(t/70)%2)creature(player.x,player.y+Math.sin(t/130)*1.4,18,player.color)}else{let glow=ctx.createRadialGradient(0,0,10,0,0,230);glow.addColorStop(0,'#b9e77820');glow.addColorStop(1,'#b9e77800');ctx.fillStyle=glow;ctx.fillRect(-230,-230,460,460);ctx.strokeStyle='#b6d68b22';for(let i=0;i<3;i++){ctx.beginPath();ctx.ellipse(0,65,100+i*45,35+i*16,0,0,7);ctx.stroke()}creature(0,Math.sin(t/500)*7,65,types[chosen].color);for(let i=0;i<18;i++){let a=i*2.4+t*.0001;circle(Math.cos(a)*(110+i*5),Math.sin(a*1.3)*130,2,'#c6ec8588')}}ctx.restore();let vignette=ctx.createRadialGradient(w*.6,h*.5,50,w*.5,h*.5,Math.max(w,h)*.75);vignette.addColorStop(0,'#08171a00');vignette.addColorStop(1,'#08171acc');ctx.fillStyle=vignette;ctx.fillRect(0,0,w,h);if(!playing){let shade=ctx.createLinearGradient(0,0,w,0);shade.addColorStop(0,'#0d1b23ee');shade.addColorStop(.48,'#0d1b2399');shade.addColorStop(1,'#0d1b2300');ctx.fillStyle=shade;ctx.fillRect(0,0,w,h)}}
function frame(t){let dt=Math.min((t-last)/1000,.04);last=t;if(mode==='play')update(dt);draw(t);requestAnimationFrame(frame)}requestAnimationFrame(frame);
